// PokeAPI → public/data/pokemon.json (Species[] for national dex 1..251)
// Usage: node scripts/build-pokemon-data.mjs [--refresh]
//   --refresh   re-download PokeAPI JSON even if cached in .cache/pokeapi/
//
// Rules (see docs/POKEMON_DATA.md, generated by this script):
//   - name/genus/flavor from the Korean ('ko') PokeAPI entries, types = current types.
//   - evolutions normalized to levels (level-up min_level | friendship 20 (baby 12) | stone 25 | trade 36 | other 28,
//     Eevee branches all 25, Tyrogue branches 20). Only species 1..251 are kept in the chain.
//   - tier 1..9 from the capture rate of the chain's basic (first non-baby) form, +2 per evolution stage (clamp 8),
//     babies tier 3, legendary/mythical tier 9 (obtainable 'event').
//   - obtainable: basic & baby → 'wild'; stage 1 → 'wild' if tier ≤ 5 else 'evolve'; stage ≥ 2 → 'evolve'.
//   - habitats: PokeAPI habitat; null/'rare' for non-legendaries → derived from types.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const REFRESH = args.includes('--refresh');
const CACHE = resolve(root, '.cache/pokeapi');
const OUT = resolve(root, 'public/data/pokemon.json');
const DOC = resolve(root, 'docs/POKEMON_DATA.md');
const MAX_ID = 251;
const CONCURRENCY = 6;
const API = 'https://pokeapi.co/api/v2';

// ---------------------------------------------------------------- tables ----
const TYPE_KO = {
  normal: '노말', fire: '불꽃', water: '물', grass: '풀', electric: '전기', ice: '얼음', fighting: '격투',
  poison: '독', ground: '땅', flying: '비행', psychic: '에스퍼', bug: '벌레', rock: '바위', ghost: '고스트',
  dragon: '드래곤', dark: '악', steel: '강철', fairy: '페어리',
};
const HABITATS = ['cave', 'forest', 'grassland', 'mountain', 'rare', 'rough-terrain', 'sea', 'urban', 'waters-edge'];
/** Habitats each encounter area uses (DESIGN §7.5). 'rare' is used by no area. */
const AREA_HABITATS = {
  route1: ['grassland', 'urban'],
  route2: ['grassland', 'forest'],
  forest: ['forest'],
  route22: ['grassland', 'waters-edge', 'sea'],
  route3: ['mountain', 'rough-terrain', 'cave', 'waters-edge'],
};
const USED_HABITATS = new Set(Object.values(AREA_HABITATS).flat());
/** Type → habitat used when PokeAPI has no usable habitat (null / 'rare' for a non-legendary). */
const TYPE_HABITAT = {
  water: 'waters-edge', rock: 'mountain', ground: 'rough-terrain', fighting: 'mountain', grass: 'forest', bug: 'forest',
  electric: 'urban', normal: 'grassland', flying: 'grassland', fairy: 'grassland', psychic: 'urban', poison: 'urban',
  ghost: 'cave', ice: 'cave', dragon: 'waters-edge', dark: 'urban', steel: 'cave', fire: 'mountain',
};
/** Dex entries containing these are skipped when another Korean entry exists (kid-friendliness). */
const VIOLENT_WORDS = ['죽', '살해', '피를', '목숨', '시체', '잡아먹', '지옥', '저주', '사별', '영혼', '갈기갈기', '태워버', '불태워', '파괴', '기절'];
/**
 * Manual overrides applied last (id → partial Species). Keep this list short and explain each entry.
 * They are also listed in docs/POKEMON_DATA.md.
 */
const OVERRIDES = {
  // 잉어킹: PokeAPI says 'waters-edge' but it is the classic fishing catch — keep both waters so it also bites at sea.
  129: { habitats: ['waters-edge', 'sea'] },
  // 안농: PokeAPI has no habitat (type fallback would give 'urban'); it lives in the ruins → cave (route3).
  201: { habitats: ['cave'] },
};

// ----------------------------------------------------------------- fetch ----
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function fetchJson(url, attempt = 0) {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(25000), headers: { 'User-Agent': 'pokemon-study-adventure/1.0 (data build script)' } });
    if (res.status === 404) return null;
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (e) {
    if (attempt >= 4) throw new Error(`${url}: ${e.message}`);
    await sleep(600 * 2 ** attempt);
    return fetchJson(url, attempt + 1);
  }
}
async function cached(kind, key, url) {
  const dir = resolve(CACHE, kind);
  mkdirSync(dir, { recursive: true });
  const file = resolve(dir, `${key}.json`);
  if (!REFRESH && existsSync(file)) return JSON.parse(readFileSync(file, 'utf8'));
  const json = await fetchJson(url);
  if (json) writeFileSync(file, JSON.stringify(json));
  return json;
}
/** Run fn over items with at most n in flight; preserves order of results. */
async function pool(items, n, fn) {
  const out = new Array(items.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(n, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      out[i] = await fn(items[i], i);
    }
  }));
  return out;
}

// Gold/Silver level-up learnsets; cache move metadata just like species data.
const learnset = p => p.moves.flatMap(m => m.version_group_details
  .filter(v => v.version_group.name === 'gold-silver' && v.move_learn_method.name === 'level-up')
  .map(v => ({ id: idFromUrl(m.move.url), level: v.level_learned_at })));

// -------------------------------------------------------------- helpers ----
const idFromUrl = (url) => Number(url.replace(/\/+$/, '').split('/').pop());
const inRange = (id) => id >= 1 && id <= MAX_ID;
const normText = (s) => s.replace(/[\n\f\r­]+/g, ' ').replace(/\s+/g, ' ').trim();

function pickFlavor(entries) {
  const ko = entries.filter((f) => f.language.name === 'ko').map((f) => normText(f.flavor_text)).filter(Boolean);
  if (!ko.length) return '';
  const uniq = [...new Set(ko)];
  const gentle = uniq.filter((t) => !VIOLENT_WORDS.some((w) => t.includes(w)));
  const cands = gentle.length ? gentle : uniq;
  return cands.sort((a, b) => a.length - b.length || a.localeCompare(b, 'ko'))[0];
}

function baseTier(captureRate) {
  if (captureRate >= 190) return 1;
  if (captureRate >= 120) return 2;
  if (captureRate >= 75) return 3;
  if (captureRate >= 45) return 4;
  if (captureRate >= 25) return 5;
  return 6;
}

/**
 * Normalize one evolution edge to a level. An edge may carry several evolution_details (version differences,
 * regional-form items such as galarica-cuff); the first entry is always the original mechanic, so:
 * any min_level → the smallest min_level; otherwise the first detail's trigger decides.
 */
function evoLevel(details, from) {
  if (from.id === 133) return 25;               // 이브이: child picks the branch
  if (from.id === 236) return 20;               // 배루키
  const levels = details.map((d) => d.min_level).filter((l) => l != null);
  if (levels.length) return Math.min(...levels);
  const d = details[0];
  if (!d) return 28;
  const trigger = d.trigger?.name;
  if (d.min_happiness != null) return from.isBaby ? 12 : 20;
  if (trigger === 'use-item') return 25;
  if (trigger === 'trade') return 36;
  return 28;                                    // time of day / stats / location / other
}

// ------------------------------------------------------------------ main ----
const ids = Array.from({ length: MAX_ID }, (_, i) => i + 1);
console.log(`Fetching ${MAX_ID} species + pokemon from PokeAPI (cache: ${CACHE}) …`);
let done = 0;
const raw = await pool(ids, CONCURRENCY, async (id) => {
  const [species, pokemon] = await Promise.all([
    cached('species', id, `${API}/pokemon-species/${id}`),
    cached('pokemon', id, `${API}/pokemon/${id}`),
  ]);
  if (!species || !pokemon) throw new Error(`missing PokeAPI data for id ${id}`);
  if (++done % 50 === 0) console.log(`  ${done}/${MAX_ID}`);
  return { species, pokemon };
});

const chainIds = [...new Set(raw.map((r) => idFromUrl(r.species.evolution_chain.url)))];
console.log(`Fetching ${chainIds.length} evolution chains …`);
const chains = new Map();
await pool(chainIds, CONCURRENCY, async (cid) => {
  chains.set(cid, await cached('chain', cid, `${API}/evolution-chain/${cid}`));
});

// Per-species chain info: stage (from first non-baby ancestor), basicId, evolvesFrom, evolvesTo.
const byId = new Map(raw.map((r) => [r.species.id, r]));
const moveIds = [...new Set(raw.flatMap(r => learnset(r.pokemon).map(m => m.id)))];
console.log(`Fetching ${moveIds.length} move definitions …`);
const moveData = new Map(await pool(moveIds, CONCURRENCY, async id => [id, await cached('move', id, `${API}/move/${id}`)]));

const chainInfo = new Map();
for (const chain of chains.values()) {
  const walk = (node, parentId, stage, basicId) => {
    const id = idFromUrl(node.species.url);
    if (!inRange(id)) {
      // out-of-range node (e.g. a Gen-4 baby at the root): skip it, children behave as if it didn't exist
      for (const c of node.evolves_to) walk(c, null, stage, basicId);
      return;
    }
    const isBaby = byId.get(id).species.is_baby;
    const myBasic = isBaby ? null : (basicId ?? id);
    const myStage = isBaby ? -1 : (basicId == null ? 0 : stage);
    const info = { id, stage: myStage, basicId: myBasic, evolvesFrom: parentId ?? undefined, evolvesTo: [] };
    chainInfo.set(id, info);
    for (const c of node.evolves_to) {
      const cid = idFromUrl(c.species.url);
      if (!inRange(cid)) continue;
      info.evolvesTo.push({ id: cid, level: evoLevel(c.evolution_details, { id, isBaby }) });
      walk(c, id, myBasic == null ? 0 : myStage + 1, myBasic);
    }
  };
  walk(chain.chain, null, 0, null);
}

const problems = [];
const species = raw.map(({ species: s, pokemon: p }) => {
  const id = s.id;
  const info = chainInfo.get(id) ?? { stage: 0, basicId: id, evolvesTo: [] };
  // Branching evolutions share one level (the smallest) so the game always offers a choice and every branch stays
  // reachable (슈륙챙이 → 강챙이 25 / 왕구리 36 would otherwise auto-evolve into 강챙이 and 왕구리 could never be obtained).
  if (info.evolvesTo.length > 1) {
    const lv = Math.min(...info.evolvesTo.map((e) => e.level));
    info.evolvesTo = info.evolvesTo.map((e) => ({ ...e, level: lv }));
  }
  const name = s.names.find((n) => n.language.name === 'ko')?.name;
  const nameEn = s.names.find((n) => n.language.name === 'en')?.name ?? p.name;
  const genus = s.genera.find((g) => g.language.name === 'ko')?.genus ?? '';
  const flavor = pickFlavor(s.flavor_text_entries);
  if (!name) problems.push(`#${id} has no Korean name`);
  if (!genus) problems.push(`#${id} has no Korean genus`);
  if (!flavor) problems.push(`#${id} has no Korean flavor text`);

  const typeNames = p.types.sort((a, b) => a.slot - b.slot).map((t) => t.type.name);
  const types = typeNames.map((t) => {
    if (!TYPE_KO[t]) throw new Error(`#${id}: unknown type ${t}`);
    return TYPE_KO[t];
  });
  const isLegendary = s.is_legendary || s.is_mythical;
  const isBaby = s.is_baby;

  // habitats
  let habitats;
  const apiHabitat = s.habitat?.name ?? null;
  if (isLegendary) habitats = ['rare'];
  else if (apiHabitat && apiHabitat !== 'rare' && HABITATS.includes(apiHabitat)) habitats = [apiHabitat];
  else {
    habitats = [];
    for (const t of typeNames) {
      let h = TYPE_HABITAT[t];
      if (t === 'water' && (p.height >= 20 || p.weight >= 1000)) h = 'sea';   // big sea creatures
      if (!habitats.includes(h)) habitats.push(h);
    }
    habitats = habitats.slice(0, 1);   // primary type decides
  }

  // tier + obtainable
  let tier, obtainable;
  if (isLegendary) { tier = 9; obtainable = 'event'; }
  else if (isBaby) { tier = 3; obtainable = 'wild'; }
  else {
    const basic = byId.get(info.basicId ?? id).species;
    tier = Math.min(8, baseTier(basic.capture_rate) + 2 * info.stage);
    obtainable = info.stage === 0 ? 'wild' : info.stage === 1 && tier <= 5 ? 'wild' : 'evolve';
  }

  const out = {
    id, name, nameEn, types, genus, flavor,
    moves: learnset(p).filter(m => moveData.get(m.id)?.damage_class.name !== 'status').map(m => {
      const data = moveData.get(m.id);
      const name = data.names.find(n => n.language.name === 'ko')?.name;
      if (!name || !TYPE_KO[data.type.name]) throw Error(`Move ${m.id}: missing Korean name/type`);
      return { ...m, name, type: TYPE_KO[data.type.name], kind: data.damage_class.name };
    }),
    height: p.height / 10, weight: p.weight / 10,
    captureRate: s.capture_rate, tier, habitats, obtainable,
    ...(info.evolvesFrom ? { evolvesFrom: info.evolvesFrom } : {}),
    evolvesTo: info.evolvesTo, isLegendary, isBaby, color: s.color.name,
  };
  return { ...out, ...(OVERRIDES[id] ?? {}) };
});

// ------------------------------------------------------------ validation ----
for (const sp of species) {
  if (sp.obtainable === 'wild' && !sp.habitats.some((h) => USED_HABITATS.has(h))) problems.push(`#${sp.id} ${sp.name} is 'wild' but no area uses habitats ${sp.habitats}`);
  if (sp.obtainable === 'evolve') {
    // must reach a 'wild' ancestor through the evolvesFrom chain
    let cur = sp, hops = 0;
    while (cur && cur.obtainable !== 'wild' && hops++ < 5) cur = cur.evolvesFrom ? species[cur.evolvesFrom - 1] : undefined;
    if (!cur || cur.obtainable !== 'wild') problems.push(`#${sp.id} ${sp.name} is 'evolve' but has no wild ancestor`);
  }
  if (sp.evolvesTo.length > 1 && new Set(sp.evolvesTo.map((e) => e.level)).size !== 1) problems.push(`#${sp.id} ${sp.name} branch levels differ`);
  for (const e of sp.evolvesTo) {
    if (species[e.id - 1].evolvesFrom !== sp.id) problems.push(`#${sp.id} → #${e.id} evolvesFrom mismatch`);
    if (!(e.level >= 1 && e.level <= 60)) problems.push(`#${sp.id} → #${e.id} odd level ${e.level}`);
  }
  if (!(sp.tier >= 1 && sp.tier <= 9)) problems.push(`#${sp.id} tier ${sp.tier}`);
  if (sp.types.length < 1 || sp.types.length > 2) problems.push(`#${sp.id} types ${sp.types}`);
}
if (problems.length) {
  for (const p of problems) console.error('PROBLEM', p);
  process.exit(1);
}

// --------------------------------------------------------------- summary ----
const count = (arr, key) => {
  const m = new Map();
  for (const x of arr) for (const k of [].concat(key(x))) m.set(k, (m.get(k) ?? 0) + 1);
  return [...m.entries()].sort((a, b) => String(a[0]).localeCompare(String(b[0]), 'en', { numeric: true }));
};
const table = (title, rows) => {
  const lines = [`| ${title} | count |`, '|---|---|', ...rows.map(([k, v]) => `| ${k} | ${v} |`)];
  return lines.join('\n');
};
const wild = species.filter((s) => s.obtainable === 'wild');
const tierRows = count(species, (s) => s.tier);
const habitatRows = count(species, (s) => s.habitats);
const wildHabitatRows = count(wild, (s) => s.habitats);
const obtainableRows = count(species, (s) => s.obtainable);
const areaRows = Object.entries(AREA_HABITATS).map(([area, hs]) => [area, wild.filter((s) => s.habitats.some((h) => hs.includes(h))).length]);
const wildTierRows = count(wild, (s) => s.tier);
const derived = species.filter((s) => !s.isLegendary && (!byId.get(s.id).species.habitat || byId.get(s.id).species.habitat.name === 'rare'));

console.log('\n' + table('tier', tierRows));
console.log('\n' + table('tier (wild only)', wildTierRows));
console.log('\n' + table('habitat', habitatRows));
console.log('\n' + table('obtainable', obtainableRows));
console.log('\n' + table('area (wild pool size, all tiers)', areaRows));
if (derived.length) console.log('\nhabitat derived from types:', derived.map((s) => `#${s.id} ${s.name} → ${s.habitats}`).join(', '));

// ------------------------------------------------------------------ write ----
mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, '[\n' + species.map((s) => JSON.stringify(s)).join(',\n') + '\n]\n');
console.log(`\nwrote ${OUT} (${species.length} species)`);

// ------------------------------------------------------------------- docs ----
const DOC_HEADER = `# 포켓몬 데이터 (POKEMON_DATA)

Generated sections below are (re)written by \`scripts/build-pokemon-data.mjs\` (data) and
\`scripts/fetch-sprites.mjs\` (sprites). Edit the scripts, not the generated blocks.
`;
function updateDocSection(file, key, body) {
  const order = ['data', 'sprites'];
  const begin = `<!-- BEGIN:${key} -->`, end = `<!-- END:${key} -->`;
  let doc = existsSync(file) ? readFileSync(file, 'utf8') : DOC_HEADER;
  const block = `${begin}\n${body.trim()}\n${end}`;
  const i = doc.indexOf(begin), j = doc.indexOf(end);
  if (i >= 0 && j > i) doc = doc.slice(0, i) + block + doc.slice(j + end.length);
  else {
    let at = -1;
    for (const later of order.slice(order.indexOf(key) + 1)) {
      const k = doc.indexOf(`<!-- BEGIN:${later} -->`);
      if (k >= 0 && (at < 0 || k < at)) at = k;
    }
    doc = at >= 0 ? doc.slice(0, at) + block + '\n\n' + doc.slice(at) : doc.trimEnd() + '\n\n' + block + '\n';
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, doc);
}

const evoExamples = [25, 133, 172, 236, 95, 61, 133]
  .filter((v, i, a) => a.indexOf(v) === i)
  .map((id) => `${species[id - 1].name}(${id}) → ${species[id - 1].evolvesTo.map((e) => `${species[e.id - 1].name} Lv${e.level}`).join(', ') || '없음'}`);
const docBody = `
## 데이터: public/data/pokemon.json

Source: PokeAPI (\`pokemon-species\`, \`pokemon\`, \`evolution-chain\`, \`move\`), cached in \`.cache/pokeapi/\`.
Regenerate with \`npm run data:pokemon\` (\`-- --refresh\` re-downloads). Output = \`Species[]\` (types.ts), index 0 = id 1.
Built ${new Date().toLocaleDateString('sv-SE')}.

### Field rules
- \`name\` / \`genus\` / \`flavor\`: Korean (\`ko\`) PokeAPI entries. \`nameEn\`: English name.
- \`moves\`: Gold/Silver level-up attacking moves (Korean name, type, learn level, physical/special kind). Runtime offers the latest four available at the current level; no available attack → 몸부림. Learning attacks does not change the saved Pokémon structure. Status moves and PP are not used; damage still follows the study-answer rule.
- \`types\`: current types (e.g. 삐삐 = 페어리), keys: ${Object.entries(TYPE_KO).map(([k, v]) => `${k}→${v}`).join(', ')}.
- \`flavor\`: the **shortest** Korean dex entry (whitespace normalized). Entries containing ${VIOLENT_WORDS.map((w) => `"${w}"`).join(', ')} are skipped when another entry exists.
- \`height\` m, \`weight\` kg, \`captureRate\` 3..255, \`color\` = PokeAPI color name.
- \`isLegendary\` = legendary **or** mythical. \`isBaby\` from PokeAPI.
- \`evolvesFrom\` / \`evolvesTo[{id, level}]\`: only species 1..251 (Gen-4 babies/evolutions are pruned, e.g. 마릴 has no evolvesFrom).
  Level normalization: level-up \`min_level\` → that level (smallest if versions differ); friendship → 20 (from a baby → 12); stone/item → 25; trade (incl. held item) → 36; other (time/stat/location) → 28.
  When an edge has several PokeAPI details the first one (the original mechanic) decides — regional-form items (galarica-cuff …) are ignored.
  이브이(133) branches (134, 135, 136, 196, 197) are all 25 — the game lets the child choose (\`ui.pickEvolution\`). 배루키(236) branches at 20.
  **Every branching species has one shared level** (the smallest of its branches), so \`evolvesTo.length > 1\` always means "offer a choice":
  ${(() => { const b = species.filter((s) => s.evolvesTo.length > 1); return b.map((s) => `${s.name}(${s.id}) Lv${s.evolvesTo[0].level} → ${s.evolvesTo.map((e) => species[e.id - 1].name).join('/')}`).join('; '); })()}.
  Examples: ${evoExamples.join('; ')}.
- \`habitats\`: PokeAPI habitat. Legendaries → \`['rare']\`. If PokeAPI has none / 'rare' for a non-legendary it is derived from the primary type
  (${Object.entries(TYPE_HABITAT).map(([k, v]) => `${k}→${v}`).join(', ')}; water species ≥ 2 m or ≥ 100 kg → sea).
  Derived this run: ${derived.length ? derived.map((s) => `${s.name}(${s.id})→${s.habitats}`).join(', ') : 'none'}.
- \`tier\` 1..9 (DESIGN §7.5): legendary/mythical → 9. Otherwise base tier from the **capture rate of the chain's basic form**
  (first non-baby form; babies do not count as a stage): ≥190→1, 120–189→2, 75–119→3, 45–74→4, 25–44→5, <25→6;
  +2 per evolution stage, clamped to 8. Babies → 3.
- \`obtainable\`: legendary → \`event\`; basics & babies → \`wild\`; stage-1 evolutions → \`wild\` if tier ≤ 5 (피죤, 레트라, 라이츄 …) else \`evolve\`; stage-2 → \`evolve\`.
  Every \`wild\` species has ≥ 1 habitat used by an area (route1: grassland, urban · route2: grassland, forest · forest: forest ·
  route22: grassland + fishing waters-edge, sea · route3: mountain, rough-terrain, cave + fishing waters-edge). The build fails otherwise.
- Encounter pool (DESIGN §7.5) = species with a matching habitat, \`tier ≤ unlocked\`, \`obtainable === 'wild'\`. \`evolve\` species still carry their
  PokeAPI habitat for dex/info purposes; the pool must filter by \`obtainable\`.

### Manual overrides
${Object.keys(OVERRIDES).length ? Object.entries(OVERRIDES).map(([id, o]) => `- #${id} ${species[id - 1].name}: ${JSON.stringify(o)}`).join('\n') : '- none'}

### Summary
${table('tier', tierRows)}

${table('tier (wild only)', wildTierRows)}

${table('habitat', habitatRows)}

${table('habitat (wild only)', wildHabitatRows)}

${table('obtainable', obtainableRows)}

${table('area (wild pool size, all tiers)', areaRows)}

### Legendary / event (tier 9)
${species.filter((s) => s.isLegendary).map((s) => `${s.name}(${s.id})`).join(', ')}

### Babies (tier 3, wild)
${species.filter((s) => s.isBaby).map((s) => `${s.name}(${s.id})`).join(', ')}
`;
updateDocSection(DOC, 'data', docBody);
console.log(`updated ${DOC}`);
